window.B1_UNITS = [
{ n:1, title:"OUTER RIM", classes:"1–2", node:"Sector 01", color:"#5bc8f5", theme:"Identifying people and things, and anchoring a moment in time",
  overview:{
    intro:"Every long journey starts with names and coordinates. This sector gives you two ways of being precise: relative clauses, which tell your listener exactly which person or thing you mean, and it-clauses with “when”, which pin a feeling or a judgement to a moment. Both let you replace two thin sentences with one adult sentence.",
    goals:["Use who and that as subjects and objects of defining relative clauses.","Decide when the relative pronoun can be omitted and when it must stay.","Build it-clauses with adverbial when to describe situations and reactions."],
    outcome:"By the end you can define any person, object or job in one sentence, and describe three situations that annoy, please or surprise you using it-clauses."
  },
  vocab:[
    {term:"to get on someone’s nerves", pos:"idiom", def:"to irritate someone, usually by repeating something.",
     use:"The thing that annoys is the subject: “It gets on my nerves when people talk loudly.”",
     examples:["It gets on my nerves when someone interrupts me.","His constant tapping got on my nerves."],
     colloc:"really get on my nerves · get on your nerves"},
    {term:"reliable", pos:"adjective", def:"that you can trust to work or to behave well.",
     use:"For people, machines and sources: “a reliable colleague”, “a reliable source”. Opposite: unreliable.",
     examples:["I need someone who is reliable.","The old laptop isn’t reliable any more."],
     colloc:"highly reliable · a reliable source · reliable service"},
    {term:"considerate", pos:"adjective", def:"thinking about other people’s feelings.",
     use:"“Considerate of / towards someone”. Not the same as “considerable”, which means large.",
     examples:["She’s a considerate neighbour who never plays loud music.","It was considerate of you to call."],
     colloc:"very considerate · considerate towards others"},
    {term:"to put up with", pos:"phrasal verb", def:"to tolerate something unpleasant without complaining.",
     use:"Three parts, always together, always with an object: “I can’t put up with it.”",
     examples:["I can’t put up with people who are always late.","She puts up with a lot at work."],
     colloc:"put up with it · can’t put up with"},
    {term:"pet peeve", pos:"noun phrase", def:"a small thing that irritates you personally.",
     use:"Countable, usually with a possessive: “my biggest pet peeve”. Informal.",
     examples:["My pet peeve is people who don’t answer messages.","Loud chewing is her pet peeve."],
     colloc:"my biggest pet peeve · a common pet peeve"},
    {term:"to look up to", pos:"phrasal verb", def:"to admire and respect someone.",
     use:"Inseparable, three parts: “I look up to her.” Opposite: “look down on”.",
     examples:["He’s someone I really look up to.","I look up to teachers who stay patient."],
     colloc:"look up to a mentor · someone to look up to"},
    {term:"trustworthy", pos:"adjective", def:"deserving to be trusted.",
     use:"For people and information: “a trustworthy witness”. Slightly more formal than “reliable”.",
     examples:["A friend is someone who is trustworthy.","Is the website trustworthy?"],
     colloc:"completely trustworthy · a trustworthy source"},
    {term:"to be into", pos:"expression", def:"to be very interested in something (informal).",
     use:"“Be into + noun / -ing”: “I’m into astronomy.” Very common in spoken English.",
     examples:["She’s really into old films.","I’m not into crowded places."],
     colloc:"really into · not into it · what are you into"},
    {term:"to drive someone crazy", pos:"idiom", def:"to annoy someone intensely.",
     use:"“It drives me crazy when…” is the standard it-clause pattern.",
     examples:["It drives me crazy when the lift is out of order.","That noise is driving me crazy."],
     colloc:"drive me crazy · drive you mad"},
    {term:"colleague", pos:"noun", def:"a person you work with.",
     use:"Countable, neutral. “Workmate” is informal; “co-worker” is common in American English.",
     examples:["I have a colleague who speaks four languages.","My colleagues are very supportive."],
     colloc:"a former colleague · a close colleague"} ],
  grammar:[
    {name:"Relative pronouns as subjects and objects; pronoun omission", short:"a person who listens · the film (that) we saw",
     rule:"A defining relative clause identifies which person or thing you mean. “Who” refers to people, “that” refers to people and things, “which” refers to things. The pronoun can replace the subject or the object of its own clause — and only the object pronoun can be left out.",
     form:["Subject pronoun (cannot be omitted): I like people who listen. / an app that works offline.","Object pronoun (can be omitted): the person (who/that) I met · the film (that) we saw.","Things: a phone which/that has a good camera.","Possession: the colleague whose laptop was stolen.","With a preposition at the end: the person (who) I spoke to."],
     notes:["Never repeat the subject or object inside the clause: “the man who he called me” and “the book that I read it” are both wrong.","Test for omission: if a noun or pronoun follows the gap, the pronoun is an object and can be dropped — “the film I saw”.","A subject pronoun can never be dropped, because the clause would have no subject: “the man lives here” is a different sentence.","“Whom” is the formal object form for people and is normally replaced by “who” or nothing in speech.","In defining clauses there are no commas. Commas turn the clause into extra information, which you will meet in sector 14."],
     deep:"Relative clauses are the fastest upgrade available at B1, because they let you say in one sentence what you previously said in two: “I have a colleague. She speaks four languages” becomes “I have a colleague who speaks four languages.” The whole mechanism reduces to a single question — what job is the relative pronoun doing inside its own clause? If it is the subject, it must stay, because English clauses cannot exist without a subject. If it is the object, the clause already has a subject, so the pronoun becomes optional and native speakers drop it constantly, which is why “the film I saw last night” sounds so much more natural than the fully marked version. The other habit to break is doubling: once the pronoun has replaced the object, nothing goes in the object slot, so “the book that I read it” contains one object too many.",
     chart:{title:"Relative pronoun choice and omission", cols:["Refers to","Subject","Object","Can it be omitted?"], rows:[["person","who / that","who(m) / that","yes, as object"],["thing","which / that","which / that","yes, as object"],["possession","whose","whose","no"],["place","where","—","no"],["time","when","—","yes: the day we met"],["Example","a friend who calls","a friend (who) I call","object only"]]},
     examples:["I admire people who admit their mistakes.","The app that I downloaded yesterday keeps crashing.","She’s the colleague I share an office with.","Anything that saves time is worth trying."],
     watch:"Do not put an extra pronoun in the clause: “the song that I like it” must be “the song that I like”."},
    {name:"It-clauses and adverbial clauses with “when”", short:"It bothers me when people are late.",
     rule:"An it-clause puts a reaction or a judgement first and the situation second. The “it” is a placeholder; the real content arrives in the “when” clause, which describes the moment or the recurring situation that produces the reaction.",
     form:["It + verb + object + when + clause → It annoys me when people cancel late.","It + be + adjective + when + clause → It’s frustrating when nobody replies.","It + be + noun + when + clause → It’s a problem when the system is down.","With “if” for a possible situation: It’s fine if you arrive late.","Reversed for emphasis: When people cancel late, it really annoys me."],
     notes:["The verbs in this pattern are all reaction verbs: annoy, bother, upset, please, surprise, worry, irritate, drive me crazy.","“When” here means “every time that”, so the clause takes the present simple even though the reaction is general.","Do not use “will” in the when-clause: “It bothers me when he will arrive late” is wrong.","The adjective version needs no object: “It’s annoying when…”, not “It’s annoying me when…” unless you really mean right now.","The whole structure can be reversed, and the when-clause then takes a comma: “When people are late, it bothers me.”"],
     deep:"English likes to delay heavy information, and the it-clause is one of its main tools for doing so. Instead of making a long situation the subject — “People cancelling arrangements at the last minute annoys me” — the sentence opens with an empty “it”, delivers the reaction immediately, and only then explains the trigger. That order is easier to process, which is why spoken English uses it constantly for opinions and complaints. The “when” inside these clauses is not really about a single occasion: it means “every time that”, which is why the tense stays in the present simple even when you are describing something habitual and irritating. Learn the two variants together — “it + verb + object” for a personal reaction (“it bothers me”) and “it + be + adjective” for a general judgement (“it’s frustrating”) — and you can react to almost anything with precision.",
     chart:{title:"It-clause patterns", cols:["Pattern","Function","Example"], rows:[["It annoys / bothers me when…","personal reaction","It annoys me when people push in."],["It’s + adjective + when…","general judgement","It’s rude when someone doesn’t reply."],["It’s + noun + when…","classifying the situation","It’s a nuisance when the wifi drops."],["It’s fine / OK if…","accepting a possibility","It’s fine if you need more time."],["It surprises me that…","reaction to a fact","It surprises me that nobody noticed."],["Reversed","emphasis on the situation","When people shout, it upsets me."]]},
     examples:["It really bothers me when people talk during films.","It’s frustrating when you wait an hour and nobody comes.","It’s not a problem when you tell me in advance.","When my neighbours play music at midnight, it drives me crazy."],
     watch:"Keep the when-clause in the present simple, and do not add an object to the adjective version: “It’s annoying when…”, not “It’s annoying me when…”."} ],
  speaking:[
    {kind:"Definitions", text:"Define ten jobs, objects or types of person without naming them, using only defining relative clauses. Your partner guesses each one."},
    {kind:"Pet peeves", text:"Share five things that get on your nerves, each as an it-clause with “when”. Your partner responds with agreement or a counter-example."},
    {kind:"Ideal team", text:"Describe the four people you would take on a long mission, each with a relative clause explaining why: “someone who…”, “a person that…”."} ],
  tips:[
    "Ask what job the pronoun does in its own clause — subject stays, object can go.",
    "Never leave an extra pronoun behind: “the film that I saw”, not “that I saw it”.",
    "The when-clause of an it-clause stays in the present simple."],
  quiz:{q:"That’s the engineer ___ fixed the navigation system.", options:["who","who she","which"], answer:0, explain:"“Who” is the subject of the relative clause, so it must stay and cannot be followed by another subject."} },

{ n:2, title:"CARGO BAY", classes:"5–6", node:"Sector 02", color:"#e8a33d", theme:"Naming activities, and measuring one thing against another",
  overview:{
    intro:"Two skills for building arguments. First, gerund phrases, which turn a whole activity into a noun so it can be the subject or object of a sentence. Second, the full comparison system: not only adjectives, but nouns, verbs and past participles, so you can compare quantities, actions and states with equal precision.",
    goals:["Use gerund phrases as subjects and objects of sentences.","Compare with adjectives, nouns, verbs and past participles.","Choose between as … as, more … than and not as … as accurately."],
    outcome:"By the end you can argue for one option over another in six sentences, each using a different comparison structure."
  },
  vocab:[
    {term:"to give up", pos:"phrasal verb", def:"to stop doing something, usually a habit.",
     use:"Followed by a noun or -ing: “give up smoking”. Separable with a pronoun: “give it up”.",
     examples:["Giving up sugar was harder than I expected.","She gave up trying to fix it."],
     colloc:"give up smoking · never give up · give it up"},
    {term:"worthwhile", pos:"adjective", def:"worth the time, money or effort involved.",
     use:"Before a noun (“a worthwhile investment”) or after “be” (“it was worthwhile”).",
     examples:["Learning a second language is worthwhile.","It was a worthwhile detour."],
     colloc:"a worthwhile experience · well worthwhile"},
    {term:"to make progress", pos:"expression", def:"to advance towards a goal.",
     use:"“Progress” is uncountable: “make good progress”, never “progresses”. Never “do progress”.",
     examples:["Practising every day is the only way to make progress.","We’ve made a lot of progress."],
     colloc:"make good progress · slow progress"},
    {term:"time-consuming", pos:"adjective", def:"taking a lot of time.",
     use:"Hyphenated before a noun: “a time-consuming process”. Also after “be”.",
     examples:["Commuting by bus is time-consuming.","The paperwork was extremely time-consuming."],
     colloc:"a time-consuming task · less time-consuming"},
    {term:"to be worth it", pos:"expression", def:"good enough to justify the cost or effort.",
     use:"“It’s worth + -ing” or “worth it”. Never an infinitive: not “worth to try”.",
     examples:["The course was expensive, but it was worth it.","It’s worth checking the price first."],
     colloc:"well worth it · not worth the trouble"},
    {term:"advantage / drawback", pos:"nouns", def:"a good point / a disadvantage.",
     use:"“The advantage of + -ing”, “the main drawback is that…”. Both countable.",
     examples:["The advantage of flying is speed.","The only drawback is the price."],
     colloc:"a big advantage · the main drawback"},
    {term:"to take up", pos:"phrasal verb", def:"to start a new activity or hobby; to occupy space or time.",
     use:"Separable: “take up running”, “it takes up too much space”.",
     examples:["I took up swimming last year.","That sofa takes up half the room."],
     colloc:"take up a hobby · take up space · take up time"},
    {term:"efficient", pos:"adjective", def:"working well without wasting time or resources.",
     use:"For systems, machines and people: “an efficient process”. Adverb: efficiently.",
     examples:["Cycling is more efficient than driving in the centre.","She’s an extremely efficient organiser."],
     colloc:"highly efficient · fuel-efficient · work efficiently"},
    {term:"to be similar to / different from", pos:"expressions", def:"comparing likeness and difference.",
     use:"Fixed prepositions: “similar to”, “different from” (also “to” in British English). Never “different than” in careful writing.",
     examples:["This model is similar to the older one.","Life here is very different from what I expected."],
     colloc:"remarkably similar to · slightly different from"},
    {term:"nowhere near", pos:"adverbial phrase", def:"not nearly; far from.",
     use:"Used to strengthen a negative comparison: “nowhere near as expensive as”.",
     examples:["It’s nowhere near as difficult as it looks.","We’re nowhere near finished."],
     colloc:"nowhere near as good as · nowhere near enough"} ],
  grammar:[
    {name:"Gerund phrases as subjects and objects", short:"Learning a language takes patience.",
     rule:"A gerund is the -ing form used as a noun. A gerund phrase — the gerund plus its own objects and modifiers — behaves as a single noun, so it can be the subject of a sentence, the object of a verb, or the object of a preposition. As a subject it always takes a singular verb.",
     form:["Subject: Learning two languages at once is demanding.","Object of a verb: I enjoy working in the evenings.","Object of a preposition: She’s good at solving problems.","Negative gerund: Not answering was a mistake.","After certain verbs only: avoid, enjoy, finish, keep, mind, suggest, recommend, consider."],
     notes:["A gerund subject is always singular, however long the phrase: “Reading long technical reports is tiring.”","Every preposition takes a gerund, never an infinitive: “interested in learning”, “instead of waiting”, “before leaving”.","Verbs of aiming take infinitives instead: want, hope, plan, decide, learn, try → “I hope to travel”.","The negative goes before the gerund: “not knowing the answer”, never “knowing not”.","The alternative “it + infinitive” pattern says almost the same thing: “Learning is useful” / “It’s useful to learn.”"],
     deep:"The gerund exists so that an action can occupy a noun’s position in a sentence. That is why it is the natural subject for generalisations: “Arriving late creates a bad impression” talks about the activity itself, not about any particular arrival. Two consequences follow. The gerund phrase behaves as one unit, so the verb agrees with the whole phrase in the singular no matter how many nouns appear inside it — a rule that catches learners out in sentences like “Managing three projects at once is exhausting”. And because prepositions require noun-like objects, every preposition is automatically followed by a gerund, which is why “I’m thinking about changing jobs” cannot become “to change”. The competing pattern, “it + adjective + infinitive”, expresses the same idea with the judgement in front; alternating between the two is what keeps a paragraph of opinions from sounding mechanical.",
     chart:{title:"Where gerund phrases go", cols:["Position","Structure","Example"], rows:[["Subject","gerund phrase + singular verb","Working from home saves time."],["Object of a verb","verb + gerund","I avoid driving at night."],["Object of a preposition","preposition + gerund","She’s tired of waiting."],["After phrasal verbs","phrasal verb + gerund","I gave up trying."],["Negative","not + gerund","Not replying was rude."],["Compare","it + adjective + infinitive","It saves time to work from home."]]},
     examples:["Studying two hours a day is more effective than studying ten hours once a week.","I don’t mind working late, but I hate starting early.","She succeeded in persuading the whole team.","Not knowing the language made everything slower."],
     watch:"A gerund subject takes a singular verb, and every preposition takes -ing: “good at solving”, never “good at to solve”."},
    {name:"Comparisons with adjectives, nouns, verbs and past participles", short:"cheaper than · as much space as · works harder than · better organised than",
     rule:"English compares four different kinds of word, and the structure changes for each. Adjectives take -er or “more”; nouns take “more / fewer / less” and “as much / many … as”; verbs take “more / less” after the verb; past participles take “more / better / worse” before them.",
     form:["Adjectives: cheaper than · more expensive than · as clean as · not as modern as.","Nouns (countable): more options than · fewer delays than · as many rooms as.","Nouns (uncountable): more space than · less noise than · as much light as.","Verbs: She works harder than I do. / I travel less than I used to.","Past participles: better organised than · more crowded than · worse designed than."],
     notes:["“Fewer” goes with countable nouns and “less” with uncountable ones: fewer people, less traffic.","With verbs the comparison word follows the verb: “He complains more than anyone”, not “He more complains”.","Past participles used as adjectives keep “more / better / worse” in front: “more relaxed”, “better paid”, never “relaxeder”.","Strengthen a comparison with much, far, a lot, slightly, a bit or nowhere near: “far more expensive”, “nowhere near as fast”.","Keep the two things comparable: “My flat is smaller than yours”, not “than you”."],
     deep:"Most learners can compare adjectives and stop there, which limits what they can argue. The system is wider: any word class can be compared, and the structure follows the class rather than the meaning. Notice that quantity comparisons split by countability, exactly as quantifiers do, so “fewer delays” and “less noise” are not interchangeable stylistic choices but grammatical requirements. Verbs are compared after the verb, which feels unnatural at first because the comparison word arrives late: “this model consumes less than the old one”. And past participles behave as adjectives that have already been formed from verbs, so they cannot take -er and must take “more”, “better” or “worse” instead. Once you can move between all four, a single argument can compare cost (adjective), features (countable noun), space (uncountable noun), performance (verb) and build quality (participle) without repeating a structure.",
     chart:{title:"Comparison structures by word class", cols:["Word class","More","Less / fewer","Equal"], rows:[["Adjective (short)","cheaper than","not as cheap as","as cheap as"],["Adjective (long)","more efficient than","less efficient than","as efficient as"],["Countable noun","more options than","fewer options than","as many options as"],["Uncountable noun","more space than","less space than","as much space as"],["Verb","works more than","works less than","works as much as"],["Past participle","better organised than","worse organised than","as well organised as"]]},
     examples:["The new terminal has more gates but fewer shops than the old one.","This engine uses less fuel and runs more quietly than the previous model.","She practises more than anyone else in the group.","The second proposal was better presented, though it was nowhere near as detailed."],
     watch:"“Fewer” with countable nouns, “less” with uncountable ones, and “more” before a past participle: “more relaxed”, never “relaxeder”."} ],
  speaking:[
    {kind:"Two options", text:"Compare two ways of doing something — commuting, studying, cooking — using one comparison of each type: adjective, countable noun, uncountable noun, verb and past participle."},
    {kind:"Gerund openers", text:"Make eight generalisations that begin with a gerund phrase. Your partner must agree or disagree and give a reason."},
    {kind:"Pitch", text:"Sell your city, your job or your favourite app to the group. Every claim must be a comparison, and you may not repeat a structure."} ],
  tips:[
    "Gerund subjects are singular, however long the phrase.",
    "Every preposition takes -ing — no exceptions.",
    "Countable takes fewer, uncountable takes less."],
  quiz:{q:"This model has ___ moving parts and uses ___ energy than the old one.", options:["fewer / less","less / fewer","fewer / fewer"], answer:0, explain:"“Parts” is countable, so it takes “fewer”; “energy” is uncountable, so it takes “less”."} },

{ n:3, title:"DOCKING RING", classes:"10–11", node:"Sector 03", color:"#4fd18b", theme:"Asking for things without demanding them",
  overview:{
    intro:"A docking manoeuvre is all negotiation. This sector covers the whole request system — modals, if-clauses and gerunds — and then the indirect forms that let you ask a stranger, an official or a superior for something without sounding like you are giving orders.",
    goals:["Make requests with can, could, would and Would you mind + -ing.","Use if-clauses to ask permission politely: Do you mind if I…?","Convert direct questions into indirect requests and questions with correct word order."],
    outcome:"By the end you can ask for six favours at three levels of politeness and get information from a stranger using only indirect questions."
  },
  vocab:[
    {term:"favour", pos:"noun", def:"a helpful action you do because someone asks.",
     use:"“Do someone a favour”, “ask a favour”. The opener “Can you do me a favour?” prepares your listener.",
     examples:["Can you do me a favour and check this?","She asked me for a favour."],
     colloc:"do me a favour · a big favour · return the favour"},
    {term:"to mind", pos:"verb", def:"to be bothered or annoyed by something.",
     use:"“Would you mind + -ing” is a request; “I don’t mind” means it is fine. Answering “yes” to “Would you mind…?” is a refusal.",
     examples:["Would you mind waiting outside?","I don’t mind at all."],
     colloc:"would you mind · never mind · I don’t mind"},
    {term:"I’m afraid", pos:"expression", def:"a softener before bad news or a refusal.",
     use:"Nothing to do with fear: “I’m afraid I can’t” is the standard polite “no”.",
     examples:["I’m afraid I can’t help you today.","I’m afraid the office is closed."],
     colloc:"I’m afraid not · I’m afraid so"},
    {term:"to wonder", pos:"verb", def:"to want to know something.",
     use:"The classic indirect opener: “I wonder where he lives.” Never invert after it.",
     examples:["I was wondering if you could help me.","I wonder why she left so early."],
     colloc:"I wonder if · I was wondering whether"},
    {term:"whether", pos:"conjunction", def:"the more formal alternative to “if” inside a reported question.",
     use:"Use it when there are two options, and always after a preposition: “it depends on whether…”.",
     examples:["Could you tell me whether the shop is open?","I’m not sure whether he got my message."],
     colloc:"whether or not · it depends on whether"},
    {term:"to hesitate", pos:"verb", def:"to pause because you are unsure.",
     use:"“Hesitate to + verb”: “Don’t hesitate to ask.” A standard polite closing in emails.",
     examples:["Don’t hesitate to contact me.","She hesitated before answering."],
     colloc:"don’t hesitate to ask · hesitate for a moment"},
    {term:"to be tied up", pos:"idiom", def:"to be too busy to do something.",
     use:"Usually with “be”: “I’m tied up until four.” A polite way of declining.",
     examples:["I’m afraid I’m tied up all morning.","He was tied up in a meeting."],
     colloc:"tied up in a meeting · tied up all day"},
    {term:"to give someone a hand", pos:"idiom", def:"to help someone.",
     use:"“Give me a hand with + noun / -ing”: “give me a hand carrying this”.",
     examples:["Could you give me a hand with these boxes?","She gave us a hand for an hour."],
     colloc:"give me a hand with · need a hand"},
    {term:"right away", pos:"adverbial phrase", def:"immediately.",
     use:"A natural way to accept a request: “I’ll do it right away.” Synonym: straight away.",
     examples:["I’ll send it right away.","He answered right away."],
     colloc:"right away · straight away"},
    {term:"appreciate", pos:"verb", def:"to be grateful for something.",
     use:"“I’d appreciate it if you could…” is a very polite request. Note the obligatory “it”.",
     examples:["I’d appreciate it if you could reply today.","I really appreciate your help."],
     colloc:"I’d appreciate it if · greatly appreciate"} ],
  grammar:[
    {name:"Requests with modals, if-clauses and gerunds", short:"Could you help? Do you mind if I sit here? Would you mind waiting?",
     rule:"English grades politeness in requests by distance from reality. “Can” is direct, “could” and “would” are hypothetical and therefore politer, and “Would you mind + -ing” is the most indirect because it asks about the other person’s feelings rather than their actions.",
     form:["Modal + base verb: Can / Could / Will / Would you open the window?","Permission for yourself: Can I / Could I / May I use your phone?","If-clause permission: Do you mind if I sit here? / Would you mind if I opened the window?","Gerund request: Would you mind opening the window?","Very polite: I’d appreciate it if you could send it today."],
     notes:["“Would you mind” takes -ing, never an infinitive: “Would you mind waiting?”","The answers to “Would you mind…?” are inverted: “No, not at all” means yes, I will. Most speakers reply “Sure” or “Of course” to avoid the confusion.","“Do you mind if I…” takes a present tense; “Would you mind if I…” takes a past form: “if I borrowed your charger”.","Longer requests are politer: adding “possibly”, “just” or a reason increases courtesy.","When you refuse, give a reason — in English a bare “no” is heard as a rebuke."],
     deep:"Politeness in English is not a vocabulary list but a strategy of leaving the other person an exit, and every step up the scale widens that exit. A bare imperative gives none. “Can you…?” asks about ability, which is theoretically refusable. “Could you…?” moves into the hypothetical, so the request is one step removed from reality. “Would you mind…?” does not ask about the action at all — it asks whether the action would bother you, which is exactly why the polarity of the answer flips. Learners lose ground in two opposite directions: some stay at the direct end and sound demanding, others use maximum politeness with close colleagues and sound cold or sarcastic. Match the level to the size of the favour and the closeness of the relationship, and remember that adding a reason does more for your tone than any extra modal.",
     chart:{title:"Politeness scale for requests", cols:["Form","Level","When to use"], rows:[["Open the window.","direct order","emergencies, close family"],["Can you open the window?","informal","friends, colleagues, small favours"],["Could you open the window?","polite","safe default in most situations"],["Do you mind if I open it?","asking permission","when you are the one acting"],["Would you mind opening it?","very polite","strangers, bigger favours"],["I’d appreciate it if you could…","formal","emails, written requests"]]},
     examples:["Could you possibly send me the file before five?","Do you mind if I join you? — Not at all.","Would you mind giving me a hand with these boxes?","I’d appreciate it if you could confirm by Friday."],
     watch:"“Would you mind” + -ing, and remember that “No, not at all” is an acceptance, not a refusal."},
    {name:"Indirect requests and questions", short:"Where is it? → Could you tell me where it is?",
     rule:"An indirect question wraps the real question inside an introductory phrase. Inside the wrapper the clause returns to statement order: the subject comes before the verb, and the auxiliaries do, does and did disappear entirely.",
     form:["Introducer + wh-word + subject + verb → Could you tell me where the station is?","With do/does: Where does she work? → Do you know where she works?","With past: Did he call? → I wonder whether he called.","Yes/no questions take if or whether: Is it open? → Do you know if it’s open?","Indirect requests: Could you ask him to call me? / I’d like to know when it closes."],
     notes:["Never invert twice: “Do you know where is the station?” is the most common error at this level.","When do/does/did disappears, the tense and the third-person -s move onto the main verb: “where he lives”, “whether she called”.","If the whole sentence starts with a question it takes a question mark; if it starts with a statement (“I wonder…”) it takes a full stop.","Common introducers: Could you tell me…, Do you know…, I wonder…, I’d like to know…, Do you have any idea….","Indirect forms are the default with strangers, officials and customer service, and in written enquiries."],
     deep:"Two grammars collide in these sentences and only one can win. A direct question uses inversion because inversion is English’s way of marking “this is a question”. In an indirect question the marking has already been done by the introducer, so the inner clause reverts to plain statement order. The clearest way to feel this is to notice that the inner clause is really the name of a piece of information: “where he lives” behaves like a noun, and you would never invert inside a noun phrase. The politeness effect follows from the same structure. By reporting your own curiosity instead of demanding an answer, you give the other person room to decline, and English speakers read that room as courtesy — which is why an indirect question is the safe choice whenever you do not know how your request will land.",
     chart:{title:"Direct to indirect", cols:["Direct question","Change","Indirect version"], rows:[["Where is the exit?","invert back","Could you tell me where the exit is?"],["What time does it open?","drop does, add -s","Do you know what time it opens?"],["Did he call you?","drop did, past on verb","I wonder if he called you."],["Can I pay by card?","normal order","Could you tell me if I can pay by card?"],["Who is that?","invert back","Do you have any idea who that is?"],["How much is it?","invert back","I’d like to know how much it is."]]},
     examples:["Could you tell me where the meeting room is?","Do you know what time the last shuttle leaves?","I wonder whether she received my message.","I’d like to know how long the repair will take."],
     watch:"After the introducer, write a statement: “…where the station is”, never “…where is the station”."} ],
  speaking:[
    {kind:"Favour chain", text:"Each student asks the next for a favour, moving one step up the politeness scale each time. The last student must refuse politely with a reason."},
    {kind:"Information desk", text:"One student staffs an information desk; the other needs six pieces of information. Every question must be indirect — a direct question loses a point."},
    {kind:"Awkward asks", text:"Ask for three genuinely awkward favours (money, time off, a lift at midnight). Choose the politeness level deliberately and explain your choice."} ],
  tips:[
    "Match politeness to the size of the favour, not to your nerves.",
    "After an introducer, the clause is a statement — delete do/does/did.",
    "Always give a reason when you refuse."],
  quiz:{q:"Could you tell me when the next shuttle ___ ?", options:["leaves","does leave","is leaving?"], answer:0, explain:"Inside an indirect question the auxiliary disappears and the clause takes statement order: “when the next shuttle leaves”."} },

{ n:4, title:"BLACK BOX", classes:"14–15", node:"Sector 04", color:"#e0554a", theme:"Reconstructing a sequence of past events",
  overview:{
    intro:"Reading the flight recorder means putting events in order. The past continuous paints the background and gets interrupted by the simple past; the past perfect reaches back behind both to mark what had already happened. Together they let you narrate anything without a timeline on the wall.",
    goals:["Contrast the past continuous and the simple past in narration.","Use the past perfect to mark the earlier of two past events.","Combine all three tenses in a single connected account."],
    outcome:"By the end you can narrate an incident in a full paragraph, with background, interruption and an earlier cause."
  },
  vocab:[
    {term:"to interrupt", pos:"verb", def:"to stop someone or something in the middle of an action.",
     use:"Transitive: “Sorry to interrupt you.” Noun: interruption. The past continuous is what gets interrupted.",
     examples:["He interrupted me while I was speaking.","The alarm interrupted the meeting."],
     colloc:"sorry to interrupt · constantly interrupt"},
    {term:"to realise", pos:"verb", def:"to understand something suddenly and clearly.",
     use:"Followed by a that-clause: “I realised that I had left it behind.” Often paired with the past perfect.",
     examples:["I only realised the problem when it was too late.","She realised she had forgotten her keys."],
     colloc:"suddenly realise · didn’t realise"},
    {term:"by the time", pos:"conjunction", def:"before or at the moment that something else happened.",
     use:"Almost always with the past perfect in the main clause: “By the time we arrived, it had finished.”",
     examples:["By the time the ambulance came, he had recovered.","By the time I checked, the file had gone."],
     colloc:"by the time we got there · by then"},
    {term:"to break down", pos:"phrasal verb", def:"to stop working (a machine or vehicle).",
     use:"Intransitive with no object: “The car broke down.” Different from “break up” (end a relationship).",
     examples:["The engine broke down halfway.","Our system broke down twice last week."],
     colloc:"break down on the road · a breakdown"},
    {term:"eventually", pos:"adverb", def:"in the end, after a long time or several problems.",
     use:"A false friend for Spanish speakers: it does not mean “possibly”.",
     examples:["Eventually they answered my email.","She eventually agreed to help."],
     colloc:"eventually arrive · eventually gave up"},
    {term:"meanwhile", pos:"adverb", def:"at the same time, in another place.",
     use:"An adverb, not a conjunction: it links sentences, not clauses. “Meanwhile, nobody had told the client.”",
     examples:["Meanwhile, the passengers were still waiting.","I’ll call them; meanwhile, you check the log."],
     colloc:"meanwhile · in the meantime"},
    {term:"to look into", pos:"phrasal verb", def:"to investigate something.",
     use:"Inseparable: “look into the problem”, “look into it”.",
     examples:["They looked into the cause for weeks.","I’ll look into it this afternoon."],
     colloc:"look into a matter · worth looking into"},
    {term:"witness", pos:"noun / verb", def:"a person who saw an event; to see an event.",
     use:"“A witness to the accident” with “to”. As a verb it takes a direct object: “She witnessed the crash.”",
     examples:["Three witnesses had seen the same thing.","He witnessed the whole incident."],
     colloc:"an eyewitness · a key witness"},
    {term:"to go off", pos:"phrasal verb", def:"(of an alarm) to start ringing; (of a bomb) to explode.",
     use:"Intransitive: “The alarm went off at three.” Also “go off” = food spoiling.",
     examples:["The smoke alarm went off while I was cooking.","The fire alarm went off twice."],
     colloc:"the alarm went off · go off suddenly"},
    {term:"delay", pos:"noun / verb", def:"a period of waiting caused by a problem.",
     use:"“A delay of two hours”, “without delay”. As a verb it takes -ing: “delayed leaving”.",
     examples:["There had been a delay of two hours before we boarded.","The storm delayed all flights."],
     colloc:"a slight delay · a long delay · without delay"} ],
  grammar:[
    {name:"Past continuous vs simple past", short:"I was cooking when the alarm went off.",
     rule:"The past continuous (was/were + -ing) describes an action in progress at a past moment — the background. The simple past describes a completed action — the event. In narration the simple past interrupts the past continuous.",
     form:["Past continuous: was / were + -ing → At eight I was still working.","Interruption: past continuous + when + simple past → I was leaving when he called.","Parallel actions: While I was cooking, she was studying.","Negative / question: I wasn’t listening. / What were you doing at ten?","Scene setting with no interruption: It was raining and nobody was talking."],
     notes:["“When” usually introduces the short completed action; “while” usually introduces the longer background one.","State verbs resist the continuous: know, believe, own, want, belong. Say “I knew”, not “I was knowing”.","Two past continuous clauses joined by “while” mean the actions overlapped completely.","The past continuous can express an interrupted plan: “I was going to call you, but I fell asleep.”","A story told entirely in the simple past has no background; one told entirely in the continuous has no events."],
     deep:"Narration in English runs on two layers and the tenses keep them apart. The past continuous is the canvas — weather, moods, activities already under way — and the simple past is the paint, the events that move the story forward. If everything is in the simple past, nothing feels more important than anything else; if everything is in the continuous, nothing ever happens. There is also a subtlety in the interrupted use worth noticing: “I was walking to the station when I saw her” implies the walk was in progress and possibly not completed, while “I walked to the station and saw her” presents both actions as finished and sequential. Choosing the continuous is therefore a way of signalling incompleteness, and that small choice carries real narrative information.",
     chart:{title:"Background and event", cols:["Pattern","Tenses","Example"], rows:[["Interruption","was -ing + when + past simple","I was sleeping when the alarm rang."],["Same, reversed","While + was -ing, past simple","While I was sleeping, the alarm rang."],["Two parallel actions","was -ing + while + was -ing","She was cooking while I was working."],["Sequence of events","past simple + past simple","I woke up, showered and left."],["Scene setting","was -ing (no interruption)","It was raining and the streets were empty."],["Interrupted plan","was going to + verb","I was going to call, but I forgot."]]},
     examples:["I was crossing the street when a car came round the corner.","While we were waiting for the shuttle, it started to rain.","What were you doing when the power went out?","She wasn’t paying attention, so she missed the announcement."],
     watch:"Do not use the continuous with state verbs: “I was knowing him” must be “I knew him”."},
    {name:"Past perfect", short:"By the time we arrived, the ship had left.",
     rule:"The past perfect (had + past participle) marks the earlier of two past events. It exists to establish order, which lets you narrate out of chronological sequence without confusing your listener.",
     form:["Affirmative: had + past participle → The ship had already left.","Negative: hadn’t + participle → They hadn’t told anyone.","Question: Had you finished before she called?","With time markers: by the time, before, after, already, just, never, yet.","Reported speech: “I lost it.” → He said he had lost it."],
     notes:["Use it only when the order matters or is not obvious. If “after” or “before” already shows the sequence, the simple past is enough: “After I sent it, she called.”","Adverb position: already, just and never go between “had” and the participle; yet goes at the end of a negative.","“By the time” almost always triggers the past perfect in the main clause: “By the time I checked, it had gone.”","It is also the tense of past causes and explanations: “I was exhausted because I hadn’t slept.”","In reported speech the past simple and present perfect both shift to the past perfect."],
     deep:"Think of the past perfect as a step behind the story rather than as a tense of its own. Your narrative sits in the simple past, and whenever you need to reach back to something that happened before that point, the past perfect takes you there and then returns you. That is why it so often appears in a subordinate clause explaining why the main event happened: “She was furious because I had forgotten the meeting.” Because its only job is ordering, it becomes optional as soon as another word supplies the order, which is why over-using it makes prose feel heavy. The B1 skill is not producing the form — “had” plus a participle is mechanically simple — but knowing when the sequence genuinely needs marking, and recognising the reduced pronunciation (“I’d finished”) that makes it hard to hear in speech.",
     chart:{title:"Past perfect and its time markers", cols:["Marker","Position","Example"], rows:[["already","between had and participle","The ship had already left."],["just","between had and participle","She had just gone when I called."],["never / always","between had and participle","I had never seen anything like it."],["yet","end of a negative","They hadn’t replied yet."],["by the time","opens the clause","By the time we arrived, it had ended."],["because","explains a past cause","I was tired because I hadn’t slept."]]},
     examples:["By the time the engineers arrived, the system had already restarted itself.","I couldn’t get in because I had left my card at home.","She had never flown before that day.","They hadn’t finished the checks yet when the storm hit."],
     watch:"Use the past perfect only for the earlier event, and drop it when “before” or “after” already makes the order clear."} ],
  speaking:[
    {kind:"Incident report", text:"Narrate a small accident or surprise. Set the scene in the past continuous, interrupt it twice with the simple past, and explain one cause with the past perfect."},
    {kind:"Alibi", text:"Two students are witnesses to the same event and are questioned separately with “What were you doing at…?”. The class checks whether their accounts match."},
    {kind:"Three-tense story", text:"Tell a story in six sentences that uses all three tenses at least twice each. Your partner flags any tense that does not earn its place."} ],
  tips:[
    "“When” takes the short event, “while” takes the long background.",
    "Past perfect only for the earlier event — and only when the order matters.",
    "State verbs never take a continuous form."],
  quiz:{q:"By the time we reached the gate, the shuttle ___ .", options:["had already left","already left","was already leaving"], answer:0, explain:"The departure happened before the arrival, so the earlier event takes the past perfect."} },

{ n:5, title:"PROTOCOL", classes:"19–20", node:"Sector 05", color:"#5bc8f5", theme:"Complex descriptions and unwritten rules",
  overview:{
    intro:"Every culture runs on rules nobody writes down. This sector gives you the grammar for describing them: noun phrases with relative clauses inside them, so you can name a complicated thing precisely, and the language of expectation — what is the custom, what you are supposed to do, what is acceptable.",
    goals:["Build noun phrases that contain relative clauses.","Express customs and expectations with it’s the custom to, be supposed to, be expected to.","State what is and is not acceptable in a given situation."],
    outcome:"By the end you can brief a visitor on six unwritten rules of your country or workplace, each in a full, precise sentence."
  },
  vocab:[
    {term:"custom", pos:"noun", def:"a traditional way of behaving in a particular society.",
     use:"Countable: “a local custom”. The phrase “it’s the custom to + verb” states a norm.",
     examples:["It’s the custom to bring a small gift.","Local customs vary a lot between regions."],
     colloc:"a local custom · an old custom · customs and traditions"},
    {term:"to be supposed to", pos:"expression", def:"expected to, according to a rule or an arrangement.",
     use:"“You’re supposed to wear ID.” In the past it usually implies the rule was broken: “I was supposed to call her.”",
     examples:["You’re supposed to check in online first.","We were supposed to start at nine."],
     colloc:"supposed to be · not supposed to"},
    {term:"acceptable", pos:"adjective", def:"good enough or allowed in a particular situation.",
     use:"“It’s (not) acceptable to + verb”. More formal than “OK”, softer than “forbidden”.",
     examples:["It’s not acceptable to arrive an hour late.","Is it acceptable to call after nine?"],
     colloc:"perfectly acceptable · socially acceptable"},
    {term:"to be expected to", pos:"expression", def:"required by other people’s assumptions.",
     use:"Passive with an infinitive: “Guests are expected to dress smartly.” Slightly more formal than “supposed to”.",
     examples:["Employees are expected to attend the briefing.","You’re expected to tip in restaurants there."],
     colloc:"widely expected to · expected to arrive"},
    {term:"to offend", pos:"verb", def:"to upset someone by breaking a social rule.",
     use:"Transitive: “It might offend your host.” Adjective: offensive. Noun: offence.",
     examples:["Refusing food can offend some hosts.","I didn’t mean to offend anyone."],
     colloc:"easily offended · cause offence"},
    {term:"norm", pos:"noun", def:"the standard or usual behaviour in a group.",
     use:"Countable, often plural: “social norms”. “The norm” means the usual thing.",
     examples:["Working from home is the norm now.","Every culture has its own norms."],
     colloc:"social norms · the norm · break a norm"},
    {term:"appropriate", pos:"adjective", def:"suitable for the situation.",
     use:"“Appropriate for / to + noun”: “appropriate for a formal dinner”. Opposite: inappropriate.",
     examples:["That’s not appropriate for a job interview.","Choose an appropriate greeting."],
     colloc:"appropriate behaviour · perfectly appropriate"},
    {term:"to frown on", pos:"phrasal verb", def:"to disapprove of something mildly.",
     use:"Usually passive: “Tipping is frowned on here.” Inseparable.",
     examples:["Arriving early is frowned on in some cultures.","Loud phone calls are frowned on."],
     colloc:"frowned on · frown upon"},
    {term:"etiquette", pos:"noun", def:"the rules of polite behaviour in a society or profession.",
     use:"Uncountable: “business etiquette”, “the etiquette of gift-giving”.",
     examples:["Email etiquette varies by company.","There’s a whole etiquette around greetings."],
     colloc:"business etiquette · basic etiquette"},
    {term:"to get away with", pos:"phrasal verb", def:"to do something wrong without being punished.",
     use:"Three parts, always with an object or -ing: “get away with arriving late”.",
     examples:["You can get away with jeans on Fridays.","He got away with it because nobody checked."],
     colloc:"get away with it · get away with murder"} ],
  grammar:[
    {name:"Noun phrases containing relative clauses", short:"the kind of behaviour that upsets people",
     rule:"A noun phrase can carry a relative clause inside it, which lets you name something complicated in a single unit. The whole phrase then behaves as one noun and can be the subject or object of the sentence.",
     form:["Head noun + relative clause: the sort of question that nobody wants to answer.","Common frames: the kind of…, the sort of…, the type of…, the one thing that…, anything that…, someone who….","Quantified heads: most people who live here · a lot of visitors who come in July.","As subject: The people who arrive first usually get the best seats.","As object: I avoid the kind of restaurant that has photos on the menu."],
     notes:["The verb agrees with the head noun, not with the noun nearest to it: “The list of names that arrived is long.”","Keep the relative clause next to the noun it describes, or it will attach to the wrong one.","“The kind of / the sort of” takes a singular or plural noun according to what you mean: “the kind of person who…”, “the kinds of people who…”.","Indefinite heads — anything, something, someone, everyone — take “that” or nothing rather than “which”.","These phrases are how English builds precise definitions, so they dominate explanation and instruction."],
     deep:"Once a relative clause can sit inside a noun phrase, you can name things you have no single word for, which is exactly what B1 conversation requires: “the sort of colleague who replies to emails at midnight”, “the kind of rule that nobody explains to you”. The engineering is simple — a head noun plus a clause that identifies it — but two things go wrong in practice. Agreement drifts, because a long phrase puts distance between the head noun and the verb, so learners write “the list of names are” when the subject is “the list”. And the clause detaches, ending up next to the wrong noun. A reliable check is to read the sentence with the whole noun phrase replaced by “it”: if the result still makes sense, the phrase is doing its job as a single unit.",
     chart:{title:"Building complex noun phrases", cols:["Head","Relative clause","Whole phrase as…"], rows:[["the kind of person","who never apologises","subject or object"],["anything","that saves time","object"],["most visitors","who come in December","subject"],["the one rule","(that) nobody explains","object"],["a colleague","whose desk is next to mine","subject"],["the place","where we first met","object of a preposition"]]},
     examples:["The kind of behaviour that annoys people most is interrupting.","Anything that isn’t written down is a custom you have to learn.","Most travellers who visit for the first time make the same mistake.","There’s one rule that nobody ever explains to newcomers."],
     watch:"Make the verb agree with the head noun: “The list of rules that arrived is long”, not “are long”."},
    {name:"Expectations: it’s the custom to, (not) supposed to, expected to, (not) acceptable to", short:"You’re supposed to take your shoes off.",
     rule:"These structures describe what people expect rather than what the law requires. “It’s the custom to” states a tradition, “be supposed to” and “be expected to” state an expectation attached to a person, and “it’s (not) acceptable to” judges whether a behaviour is allowed socially.",
     form:["It’s the custom to + verb → It’s the custom to greet everyone individually.","subject + be supposed to + verb → You’re supposed to arrive ten minutes early.","subject + be expected to + verb → Guests are expected to bring something.","It’s (not) acceptable to + verb → It’s not acceptable to check your phone at dinner.","Negatives: You’re not supposed to smoke here. / It isn’t the custom to tip."],
     notes:["“Be supposed to” in the past usually implies the expectation was not met: “I was supposed to call her yesterday.”","“Be expected to” is a passive, so it can name the expecting party with “by”: “Staff are expected by management to…”.","“It’s the custom to” describes a whole society; “be supposed to” describes an individual’s obligation.","These are softer than “must” and “have to”, which state rules rather than expectations — a useful distinction when advising visitors.","Add a hedge for accuracy: “generally”, “usually”, “in most places”. Cultural claims are safer when they are not absolute."],
     deep:"Rules and expectations are different things, and B1 is where the distinction becomes expressible. “You must show your passport” is a regulation with a consequence; “you’re supposed to shake hands” is a social expectation whose only sanction is other people’s reaction. That is why these structures are the natural language of cultural briefing: they describe pressure without claiming legal force. Two of them deserve special attention. “Be supposed to” carries a strong implication of failure in the past — “I was supposed to send it” almost always means you did not — so use it carefully when reporting your own behaviour. And “it’s not acceptable to” is genuinely strong in English, close to a reprimand, so for milder disapproval reach for “it’s frowned on” or “people don’t usually”. Hedging is not weakness here; it is accuracy, because customs are rarely universal.",
     chart:{title:"Expressing expectations", cols:["Structure","Strength","Example"], rows:[["It’s the custom to…","tradition, neutral","It’s the custom to bring flowers."],["People usually / tend to…","description, hedged","People usually arrive a bit late."],["You’re supposed to…","expectation on a person","You’re supposed to book in advance."],["You’re expected to…","expectation, slightly formal","Guests are expected to dress smartly."],["It’s frowned on to…","mild disapproval","It’s frowned on to leave early."],["It’s not acceptable to…","strong disapproval","It’s not acceptable to shout at staff."]]},
     examples:["In many offices you’re supposed to say good morning to everyone individually.","It’s the custom to take a small gift when you visit someone’s home.","Visitors are expected to remove their shoes at the door.","It’s generally not acceptable to arrive more than ten minutes late for dinner."],
     watch:"“I was supposed to” usually means you did not do it. If you did, say “I had to”."} ],
  speaking:[
    {kind:"Culture briefing", text:"Brief a newcomer on six unwritten rules of your country or workplace, using a different expectation structure for each."},
    {kind:"Precise definitions", text:"Describe five things you dislike using complex noun phrases only: “the kind of person who…”, “anything that…”."},
    {kind:"Mistakes", text:"Tell the group about a time you broke a social rule. Explain what you were supposed to do and what actually happened."} ],
  tips:[
    "Make the verb agree with the head noun, not the nearest noun.",
    "“Supposed to” in the past implies you didn’t do it.",
    "Hedge cultural claims — “usually”, “in most places” — they are rarely absolute."],
  quiz:{q:"We ___ to submit the form last Friday, but nobody told us.", options:["were supposed","are supposed","had supposed"], answer:0, explain:"“Be supposed to” in the past expresses an expectation that was not met, so the past form “were supposed to” is correct."} },

{ n:6, title:"MALFUNCTION", classes:"23–24", node:"Sector 06", color:"#e8a33d", theme:"Describing what is broken and what it needs",
  overview:{
    intro:"Something is always broken on a working ship. This sector gives you the two halves of a repair report: describing the fault, using past participles as adjectives and the right nouns, and stating the remedy with need + gerund, need + passive infinitive, and keep + gerund for problems that will not go away.",
    goals:["Describe faults with past participles as adjectives and with problem nouns.","State what is required with need + gerund and need + passive infinitive.","Describe recurring faults with keep + gerund."],
    outcome:"By the end you can report five faults precisely and say what each one needs, in the register a technician would accept."
  },
  vocab:[
    {term:"cracked", pos:"past participle / adjective", def:"with a line of damage but not in pieces.",
     use:"Before a noun (“a cracked screen”) or after “be” (“the screen is cracked”).",
     examples:["The screen is cracked in the corner.","There’s a cracked tile in the bathroom."],
     colloc:"a cracked screen · badly cracked"},
    {term:"scratched / dented", pos:"past participles", def:"with surface marks / with a hollow from an impact.",
     use:"Both work as adjectives: “a scratched lens”, “a dented door”.",
     examples:["The lens arrived scratched.","The panel is slightly dented."],
     colloc:"badly scratched · a dented bumper"},
    {term:"leak", pos:"noun / verb", def:"an escape of liquid or gas through a hole.",
     use:"Noun: “a leak in the pipe”. Verb: “the pipe is leaking”.",
     examples:["There’s a leak under the sink.","The coolant tank has been leaking for days."],
     colloc:"a slow leak · fix a leak · leaking pipe"},
    {term:"stain", pos:"noun / verb", def:"a mark that is difficult to remove.",
     use:"Noun: “a coffee stain”. Adjective form: stained. Verb: “it stained the carpet”.",
     examples:["There’s a stain on the seat cover.","The upholstery is badly stained."],
     colloc:"a stubborn stain · remove a stain"},
    {term:"loose", pos:"adjective", def:"not firmly fixed in place.",
     use:"Careful with pronunciation and spelling: “loose” (adjective) versus “lose” (verb).",
     examples:["One of the handles is loose.","There’s a loose wire behind the panel."],
     colloc:"a loose screw · come loose"},
    {term:"faulty", pos:"adjective", def:"not working correctly because of a defect.",
     use:"Before a noun: “a faulty sensor”. The noun is “fault” or “defect”.",
     examples:["We received a faulty unit.","The fault is in the wiring, not the software."],
     colloc:"a faulty component · a manufacturing fault"},
    {term:"to fix / to repair", pos:"verbs", def:"to make something work again.",
     use:"“Fix” is everyday, “repair” is slightly more formal and used for larger jobs.",
     examples:["It needs fixing before Monday.","The panel has to be repaired, not replaced."],
     colloc:"fix a problem · repair the damage"},
    {term:"to replace", pos:"verb", def:"to put a new thing in place of an old one.",
     use:"“Replace X with Y”: “replace the battery with a new one”. Noun: replacement.",
     examples:["The filter needs to be replaced every month.","We replaced the whole unit."],
     colloc:"replace a part · a replacement unit"},
    {term:"to keep + -ing", pos:"pattern", def:"to do something repeatedly or continuously.",
     use:"Followed only by -ing: “it keeps crashing”. “Keep on + -ing” adds insistence.",
     examples:["The engine keeps cutting out.","It keeps making a strange noise."],
     colloc:"keeps happening · keep on trying"},
    {term:"warranty", pos:"noun", def:"a written promise to repair or replace a product.",
     use:"Countable: “under warranty”, “a two-year warranty”.",
     examples:["It’s still under warranty.","The warranty doesn’t cover accidental damage."],
     colloc:"under warranty · a limited warranty"} ],
  grammar:[
    {name:"Describing problems with past participles as adjectives and with nouns", short:"The screen is cracked. There’s a crack in the screen.",
     rule:"English describes a fault in two parallel ways: with a past participle used as an adjective, which focuses on the state of the object, and with a problem noun, which names the fault itself. Both are correct and they are often interchangeable.",
     form:["Participle after be: The screen is cracked. / The seat is stained.","Participle before a noun: a cracked screen · a stained seat · a dented panel.","Problem noun with there is/are: There’s a crack in the screen. / There are two dents.","Problem noun with have: The screen has a crack in it.","Negative state: It isn’t working. / It doesn’t work."],
     notes:["Participles keep their irregular forms: broken, torn, worn, bent, burnt, frozen.","Some faults exist only as nouns (a leak, a scratch, a hole, a stain, a dent) and some only as participles (jammed, blocked).","With “there is / there are”, the number agrees with the noun: “There’s a dent”, “There are three dents”.","Add a location and a degree for a useful report: “badly cracked in the top corner”.","“Broken” covers both “in pieces” and “not working”, so add detail when the difference matters."],
     deep:"A repair report is judged on precision, and English gives you two grammatical routes to it. The participle route puts the object first and its state second — “the panel is dented” — which suits a checklist of components. The noun route names the defect and locates it — “there’s a dent in the panel” — which suits a description of damage where the number and position matter. Learning both means you can vary a list of faults instead of repeating one pattern six times. Two practical notes: not every fault has both forms, so “a leak” has no participle equivalent and “jammed” has no common noun, and the participles are irregular often enough that they need memorising alongside their verbs. Finally, a good report always adds degree and location, because “cracked” and “badly cracked along the bottom edge” lead to very different responses.",
     chart:{title:"Two ways of describing the same fault", cols:["Fault","Participle","Noun"], rows:[["crack","The screen is cracked.","There’s a crack in the screen."],["dent","The door is dented.","There’s a dent in the door."],["scratch","The lens is scratched.","There are scratches on the lens."],["stain","The seat is stained.","There’s a stain on the seat."],["tear","The cover is torn.","There’s a tear in the cover."],["leak","—","There’s a leak in the pipe."],["blockage","The drain is blocked.","There’s a blockage in the drain."]]},
     examples:["The rear panel is badly dented and one of the clips is broken.","There’s a small crack in the housing and a leak underneath.","Two of the seats are stained and the armrest is loose.","The connector isn’t damaged, but the cable is worn where it bends."],
     watch:"Use the correct irregular participle: torn, worn, broken, bent — not “teared” or “breaked”."},
    {name:"Need + gerund, need + passive infinitive, and keep + gerund", short:"It needs fixing. / It needs to be fixed. / It keeps crashing.",
     rule:"When a thing requires an action, English offers two equivalent structures: “need + gerund” and “need + passive infinitive”. Both mean the same thing and the object is the subject. “Keep + gerund” describes a fault that happens repeatedly.",
     form:["need + gerund: The filter needs replacing.","need + passive infinitive: The filter needs to be replaced.","With a person as subject: I need to replace the filter. (active, ordinary need)","keep + gerund: The engine keeps stalling.","keep on + gerund for insistence: It keeps on doing it."],
     notes:["“Needs replacing” and “needs to be replaced” are interchangeable; the gerund version is more spoken, the passive infinitive slightly more formal.","Do not mix them: “needs to replacing” and “needs be replaced” are both wrong.","When a person is the subject, “need” takes an ordinary active infinitive: “I need to check the wiring.”","“Keep” is always followed by -ing, never an infinitive: “it keeps crashing”, not “it keeps to crash”.","“Want” can replace “need” in the gerund pattern in informal British English: “that door wants painting”."],
     deep:"These two structures solve a small puzzle: how to say that something requires an action without naming who will do it. “The filter needs replacing” and “the filter needs to be replaced” both leave the technician out of the sentence, which is exactly right in a fault report where the agent is irrelevant. The trap is hybrid forms — “needs to replacing”, “needs be replaced” — which come from starting one pattern and finishing the other, so practise them as two separate whole units rather than as variations. “Keep + gerund” adds the dimension that matters most in diagnostics: recurrence. A fault that happens once and a fault that keeps happening call for different responses, and English marks the difference with this single verb. Note that “keep” also means “continue”, so context decides between “it keeps crashing” (repeatedly) and “keep pressing” (continuously).",
     chart:{title:"Need and keep patterns", cols:["Structure","Subject","Example"], rows:[["need + gerund","the thing","The brakes need adjusting."],["need + passive infinitive","the thing","The brakes need to be adjusted."],["need + active infinitive","the person","I need to adjust the brakes."],["keep + gerund","the thing","The alarm keeps going off."],["keep on + gerund","the thing / person","It keeps on cutting out."],["Wrong","—","needs to replacing ✘ / keeps to crash ✘"]]},
     examples:["The coolant tank needs draining before the next flight.","Two of the seals need to be replaced, and the third needs cleaning.","The display keeps freezing whenever we restart the system.","I need to run the diagnostics again, because it keeps failing the same test."],
     watch:"“Needs fixing” or “needs to be fixed” — never “needs to fixing”. And “keep” always takes -ing."} ],
  speaking:[
    {kind:"Fault report", text:"Report five faults in a room, a vehicle or a device. Describe each one twice — once with a participle, once with a noun — then say what it needs."},
    {kind:"Complaint call", text:"One student is a customer with three problems, the other is support. The customer must use “need + gerund” and “keep + gerund” at least twice each."},
    {kind:"Diagnosis", text:"Describe a recurring problem in your daily life without naming the cause. The group asks questions and proposes what needs to be done."} ],
  tips:[
    "Two routes to the same report: “is cracked” or “there’s a crack in”.",
    "“Needs fixing” = “needs to be fixed”. Never mix the halves.",
    "“Keep” always takes -ing."],
  quiz:{q:"The air filter ___ every three months.", options:["needs to be replaced","needs to replacing","needs replace"], answer:0, explain:"“Need” takes either a gerund (“needs replacing”) or a passive infinitive (“needs to be replaced”), never a mixture."} },

{ n:7, title:"IMPACT", classes:"28–29", node:"Sector 07", color:"#4fd18b", theme:"What is being done, what caused it, and why",
  overview:{
    intro:"When the action matters more than the actor, the passive takes over. This sector covers the passive in the present continuous and present perfect — the tenses of work in progress and results so far — together with the prepositions that assign cause, and the infinitive clauses that express purpose.",
    goals:["Form the passive in the present continuous and present perfect.","Use prepositions of cause: because of, due to, as a result of, thanks to.","Express purpose and result with infinitive clauses and phrases."],
    outcome:"By the end you can describe an ongoing situation, name its causes and state what is being done about it, in the register of a report."
  },
  vocab:[
    {term:"to be under way", pos:"expression", def:"already happening, in progress.",
     use:"With “be”: “Repairs are under way.” Two words in British English.",
     examples:["An investigation is already under way.","Construction has been under way since March."],
     colloc:"already under way · get under way"},
    {term:"to carry out", pos:"phrasal verb", def:"to perform or complete a task or study.",
     use:"Separable: “carry out a survey”, “carry it out”. Very common in the passive.",
     examples:["Tests are being carried out this week.","The repairs were carried out overnight."],
     colloc:"carry out research · carry out an inspection"},
    {term:"due to", pos:"preposition", def:"because of.",
     use:"Followed by a noun or -ing, never a clause: “due to heavy rain”, not “due to it rained”.",
     examples:["The delay was due to a technical fault.","Due to demand, we’ve added a second session."],
     colloc:"due to bad weather · largely due to"},
    {term:"as a result of", pos:"preposition phrase", def:"caused by.",
     use:"Followed by a noun: “as a result of the storm”. The adverb version is “as a result”.",
     examples:["Two flights were cancelled as a result of the storm.","As a result, we lost a whole day."],
     colloc:"as a result of · as a direct result of"},
    {term:"thanks to", pos:"preposition", def:"because of — usually with a positive result.",
     use:"Followed by a noun: “thanks to the crew”. Can be ironic: “thanks to the delay, we missed it”.",
     examples:["Thanks to the new system, waiting times have halved.","We finished early thanks to Ana."],
     colloc:"thanks to your help · largely thanks to"},
    {term:"consequence", pos:"noun", def:"a result, usually a serious one.",
     use:"“The consequences of + noun”, “as a consequence”. More formal than “result”.",
     examples:["The consequences of the fault are still being assessed.","As a consequence, the launch was postponed."],
     colloc:"serious consequences · face the consequences"},
    {term:"to affect / effect", pos:"verb / noun", def:"to influence something / the result of an influence.",
     use:"“Affect” is the verb, “effect” the noun: “The delay affected everyone”, “the effect was serious”.",
     examples:["The storm affected all departures.","The new rule has had a big effect."],
     colloc:"seriously affect · have an effect on"},
    {term:"to be assessed", pos:"passive form", def:"to be examined and judged.",
     use:"Common in reports: “The damage is being assessed.” Noun: assessment.",
     examples:["The damage is still being assessed.","Applications have been assessed by two reviewers."],
     colloc:"be assessed by · a full assessment"},
    {term:"ongoing", pos:"adjective", def:"still happening.",
     use:"Before a noun: “an ongoing investigation”. Do not use after “be” in careful writing.",
     examples:["It’s an ongoing problem.","The ongoing repairs will finish on Friday."],
     colloc:"an ongoing investigation · ongoing support"},
    {term:"in order to", pos:"conjunction", def:"a more formal way of saying “to” when giving a reason.",
     use:"“In order to + verb”, and the negative “in order not to + verb”.",
     examples:["We closed the deck in order to carry out repairs.","She whispered in order not to wake him."],
     colloc:"in order to · in order not to · so as to"} ],
  grammar:[
    {name:"Passive in the present continuous and present perfect; prepositions of cause", short:"The hull is being repaired. Three panels have been replaced.",
     rule:"The passive is formed with “be” plus a past participle, and the tense lives entirely in “be”. The present continuous passive describes work in progress; the present perfect passive describes what has been completed so far. Prepositions of cause then attach the reason.",
     form:["Present continuous passive: is / are being + participle → The system is being upgraded.","Present perfect passive: has / have been + participle → Three faults have been fixed.","Negative / question: It isn’t being repaired. / Has it been tested?","With by + agent, only when the agent matters: The report has been signed by the director.","Cause: because of / due to / as a result of / thanks to / owing to + noun."],
     notes:["The tense sits in “be”, so the second word is always a participle: “is being repaired”, “has been repaired”.","Drop “by + agent” when the agent is unknown, obvious or irrelevant — which is most of the time in reports.","“Because” takes a clause, while “because of”, “due to”, “as a result of” and “thanks to” take a noun or gerund.","Only transitive verbs have a passive: happen, arrive and occur cannot be passivised.","“Being” appears only in the continuous passive; “has being repaired” is always wrong."],
     deep:"The passive is a spotlight rather than a politeness device. Every sentence has a topic, and English puts the topic in the subject position; when the interesting thing is the object of the action, the passive keeps it at the front and preserves the flow of a paragraph. That is why status reports live in these two tenses: the present continuous passive tells your reader what is happening right now (“the pipes are being replaced”), and the present perfect passive tells them the score so far (“two sections have been completed”). The prepositions of cause complete the picture, and the only real difficulty is grammatical category: “because” introduces a clause, everything else introduces a noun. Getting that wrong produces “due to it was raining”, which is the commonest cause error at this level. If you can see a subject and a verb, you need “because”.",
     chart:{title:"Passive forms and cause expressions", cols:["Form / expression","Followed by","Example"], rows:[["is / are being + participle","—","The deck is being cleaned."],["has / have been + participle","—","The fault has been identified."],["because","clause","We stopped because the pump failed."],["because of / due to","noun / -ing","We stopped due to a pump failure."],["as a result of","noun","Delays occurred as a result of the storm."],["thanks to","noun (positive)","Thanks to the crew, nobody was hurt."],["Wrong","—","due to it failed ✘ / has being cleaned ✘"]]},
     examples:["The navigation module is being replaced because of a software fault.","Three of the six sensors have already been recalibrated.","Due to the delay, the inspection has been postponed until Monday.","Thanks to the maintenance team, the system has been running without errors for a week."],
     watch:"“Because” + clause, “because of / due to” + noun. And the participle after “be”: “has been repaired”, never “has being repaired”."},
    {name:"Infinitive clauses and phrases", short:"We closed the bay to carry out repairs.",
     rule:"An infinitive clause expresses purpose, intention or a further comment. Most often it answers “why?”: “to + verb”, or the more formal “in order to / so as to”. It can also follow adjectives and nouns to complete their meaning.",
     form:["Purpose: I called to confirm the time. / in order to confirm / so as to confirm.","Negative purpose: in order not to / so as not to → I left early so as not to miss it.","With a different subject: for + object + infinitive → We closed the bay for the engineers to work safely.","After adjectives: difficult to explain · ready to launch · the first to arrive.","After nouns: the decision to postpone · a chance to speak · nothing to do."],
     notes:["“For + verb” is impossible: never “for to open”. Purpose is “to open”; function is “for opening”.","The negative purpose form is “in order not to”, not “to not”: “in order not to lose data”.","When the two clauses have different subjects, English uses “for + object + infinitive”: “There’s too much noise for me to concentrate.”","Some nouns and adjectives take a fixed infinitive: “the ability to”, “a decision to”, “likely to”, “willing to”.","A bare “to + verb” is the default; “in order to” and “so as to” raise the register."],
     deep:"Infinitives look forward, which is why they carry purpose so naturally: “to + verb” always names something not yet achieved. That single idea explains most of the pattern’s uses — reasons (“I came to help”), plans (“a decision to wait”), potential (“ready to launch”) and evaluations (“hard to explain”). Two structures raise your precision. The negative purpose form must be “in order not to” or “so as not to”, because a bare “to not” is not accepted in careful English, and this is the error examiners notice. And “for + object + infinitive” solves the problem of two different subjects, letting you say who the purpose is for: “We rescheduled the briefing for the new crew to attend.” Once you control that pattern, you can express purpose in sentences where the person acting is not the person planning.",
     chart:{title:"Infinitive clause uses", cols:["Use","Structure","Example"], rows:[["Purpose","to / in order to + verb","We stopped to refuel."],["Negative purpose","in order not to + verb","We left early in order not to be late."],["Different subject","for + object + infinitive","It’s too dark for us to work."],["After an adjective","adjective + to + verb","The system is ready to launch."],["After a noun","noun + to + verb","There was no time to check."],["Result (too / enough)","too … to / enough … to","It’s too heavy to lift."]]},
     examples:["The bay has been sealed in order to carry out pressure tests.","There isn’t enough time for the team to run a full diagnostic.","She was the first to notice that the readings had changed.","We postponed the launch so as not to risk a second failure."],
     watch:"Never write “for + infinitive” for purpose, and use “in order not to”, not “to not”."} ],
  speaking:[
    {kind:"Status report", text:"Report on a project in six sentences: three in the present continuous passive, three in the present perfect passive. Add a cause to each."},
    {kind:"Cause and effect", text:"Give six statements of cause, alternating between “because” and a preposition of cause. Your partner corrects any mismatch."},
    {kind:"Why we did it", text:"Explain five decisions using infinitive clauses of purpose, including one negative purpose and one with “for + object”."} ],
  tips:[
    "The tense lives in “be”; the second word is always a participle.",
    "“Because” + clause, “due to” + noun.",
    "Negative purpose is “in order not to”, never “to not”."],
  quiz:{q:"The engine ___ at the moment, ___ a faulty sensor.", options:["is being tested / due to","is tested / because","has being tested / due to"], answer:0, explain:"Work in progress takes the present continuous passive, and “due to” is followed by a noun phrase."} },

{ n:8, title:"COURSE CHANGE", classes:"32–33", node:"Sector 08", color:"#5bc8f5", theme:"Stating a preference, and explaining the method",
  overview:{
    intro:"Two practical structures. “Would rather” and “would prefer” let you state a preference precisely, including preferences about what other people do. “By + gerund” explains the method — how a result is achieved — which is the backbone of every instruction and every explanation of process.",
    goals:["State preferences with would rather and would prefer, in the affirmative, negative and interrogative.","Express preferences about other people’s actions with would rather + past.","Explain method and means with by + gerund and with + noun."],
    outcome:"By the end you can negotiate a plan by stating preferences precisely, and explain how any result was achieved in three steps."
  },
  vocab:[
    {term:"to would rather", pos:"semi-modal", def:"to prefer to do something.",
     use:"Always “would rather + base verb”: “I’d rather stay.” Negative: “I’d rather not”.",
     examples:["I’d rather walk than wait for the bus.","I’d rather not talk about it."],
     colloc:"I’d rather not · would you rather"},
    {term:"to would prefer", pos:"expression", def:"to prefer — followed by an infinitive or a noun.",
     use:"“I’d prefer to walk”, “I’d prefer coffee”. With a comparison: “I’d prefer tea to coffee”.",
     examples:["I’d prefer to meet in the morning.","She’d prefer the earlier flight."],
     colloc:"I’d prefer to · I’d prefer not to"},
    {term:"to be keen on", pos:"expression", def:"to be enthusiastic about something.",
     use:"“Keen on + noun / -ing”: “keen on cycling”. Often negative: “I’m not keen on it”.",
     examples:["I’m not keen on flying at night.","She’s very keen on the idea."],
     colloc:"not too keen on · keen on the idea"},
    {term:"method", pos:"noun", def:"a way of doing something.",
     use:"Countable: “a reliable method”. “The method of + -ing” or “a method for + -ing”.",
     examples:["There’s a faster method of doing this.","We changed our method halfway through."],
     colloc:"a reliable method · a new method"},
    {term:"means", pos:"noun", def:"the way or the tools by which something is achieved.",
     use:"Same form in singular and plural: “a means of transport”, “by means of”. Never “a mean”.",
     examples:["Email is the quickest means of reaching them.","We got in by means of a side door."],
     colloc:"a means of transport · by means of"},
    {term:"to work out", pos:"phrasal verb", def:"to calculate or find a solution; to end well.",
     use:"Separable: “work out the cost”, “work it out”. Also intransitive: “it worked out fine”.",
     examples:["We worked out the cost by adding the fees.","It all worked out in the end."],
     colloc:"work out a solution · work it out"},
    {term:"to cut down on", pos:"phrasal verb", def:"to reduce the amount of something.",
     use:"Three parts, followed by a noun or -ing: “cut down on sugar”, “cut down on spending”.",
     examples:["We cut costs by cutting down on travel.","She’s cutting down on coffee."],
     colloc:"cut down on spending · cut down on waste"},
    {term:"gradually", pos:"adverb", def:"slowly, over a period of time.",
     use:"Usually before the verb: “Things gradually improved.” Useful in method descriptions.",
     examples:["You can improve gradually by practising daily.","The noise gradually stopped."],
     colloc:"gradually increase · gradually improve"},
    {term:"instead of", pos:"preposition", def:"in place of.",
     use:"Followed by a noun or -ing, never an infinitive: “instead of waiting”.",
     examples:["We saved time by taking the tunnel instead of the bridge.","Instead of complaining, do something."],
     colloc:"instead of that · rather than"},
    {term:"to be worth doing", pos:"pattern", def:"good enough to justify the effort.",
     use:"“Worth + -ing”: “worth trying”. Never “worth to try”.",
     examples:["It’s worth checking the manual first.","That approach isn’t worth trying again."],
     colloc:"well worth doing · not worth it"} ],
  grammar:[
    {name:"Would rather and would prefer", short:"I’d rather walk. / I’d prefer to walk. / I’d rather you didn’t.",
     rule:"Both express preference. “Would rather” is followed by a base verb; “would prefer” by an infinitive or a noun. For a preference about someone else’s behaviour, “would rather” takes a clause with a past form.",
     form:["I’d rather + base verb → I’d rather stay here.","I’d rather + base verb + than + base verb → I’d rather walk than drive.","I’d prefer + to + verb → I’d prefer to stay here.","I’d prefer + noun (+ to + noun) → I’d prefer tea to coffee.","About someone else: I’d rather you didn’t smoke here. (past form, present meaning)"],
     notes:["“Would rather” takes no “to”: “I’d rather go”, never “I’d rather to go”.","The comparison word differs: “rather … than”, but “prefer … to”. Mixing them produces “prefer than”, which is wrong.","Negatives attach to “rather” and “prefer”, not to the verb: “I’d rather not go”, “I’d prefer not to go”.","“I’d rather you + past form” is the polite way to ask someone to change their behaviour — the past form signals unreality, not past time.","Questions: “Would you rather stay or go?” and “Which would you prefer?”"],
     deep:"These two structures do the same job with different grammar, and the errors come from crossing them. “Rather” is an adverb attached directly to a bare verb, so nothing comes between them; “prefer” is a full verb, so it needs “to” before another verb. Their comparison words are equally fixed: “rather … than” and “prefer … to”. Once those are automatic, the interesting form is “I’d rather you didn’t”, which uses a past tense with present meaning — the same unreality marker you meet in second conditionals and after “wish”. It is one of the most useful polite structures in English, because it expresses a request as your own preference rather than as an instruction: “I’d rather you called before coming” is a great deal gentler than “don’t come without calling”, and native speakers use it constantly to manage other people’s behaviour without confrontation.",
     chart:{title:"Would rather / would prefer", cols:["Meaning","would rather","would prefer"], rows:[["Simple preference","I’d rather stay.","I’d prefer to stay."],["Comparison","I’d rather stay than go.","I’d prefer staying to going."],["With a noun","—","I’d prefer the earlier flight."],["Negative","I’d rather not stay.","I’d prefer not to stay."],["About someone else","I’d rather you didn’t stay.","I’d prefer it if you didn’t stay."],["Question","Would you rather stay?","Would you prefer to stay?"]]},
     examples:["I’d rather take the night shuttle than wait until morning.","She’d prefer to review the figures before the meeting.","I’d rather not comment until the report is finished.","I’d rather you told me now than in a week’s time."],
     watch:"“Rather” takes a bare verb and “than”; “prefer” takes “to + verb” and “to”. Never “prefer than”."},
    {name:"By + gerund to describe how to do things", short:"You can save fuel by flying lower.",
     rule:"“By + gerund” names the method: the action through which a result is achieved. It answers the question “how?”. The related structure “with + noun” names the instrument rather than the action.",
     form:["Result + by + gerund → We reduced costs by cutting travel.","By + gerund first, with a comma → By checking twice, we avoided the error.","Negative method: by not + gerund → You save time by not repeating the test.","Instrument: with + noun → Open it with a screwdriver.","Without a method: without + gerund → We finished without asking for help."],
     notes:["“By” is a preposition, so the verb after it always takes -ing: “by adding”, never “by add” or “by to add”.","“By” names an action; “with” names a tool or a material: “by cutting the cable” versus “with a knife”.","The negative goes before the gerund: “by not sending it twice”.","“Through” can replace “by” with abstract nouns: “through careful planning”.","Do not confuse this “by” with the passive agent “by”, which is followed by a noun: “written by an engineer”."],
     deep:"“By + gerund” is the grammar of method, and it is what turns a list of actions into an explanation. Compare “we cut costs — we reduced travel” with “we cut costs by reducing travel”: the second states the causal link explicitly, and that link is exactly what a reader or examiner is looking for in an explanation. Because “by” is a preposition, the gerund is obligatory, which makes this one of the safest structures in English once you have internalised it. Two refinements are worth having. The contrast with “with” is real: “with” introduces the instrument (“with a spanner”) while “by” introduces the action (“by tightening the bolts”), and using the wrong one is immediately noticeable. And the negative form, “by not + gerund”, lets you explain a method that consists of avoidance, which is often the most useful advice you can give.",
     chart:{title:"Method, instrument and absence", cols:["Structure","Names","Example"], rows:[["by + gerund","the action / method","We saved time by automating it."],["by not + gerund","avoidance as method","You avoid errors by not rushing."],["with + noun","the instrument","Loosen it with a spanner."],["through + noun","abstract means","We succeeded through persistence."],["without + gerund","absence of an action","They finished without asking."],["Passive by + noun","the agent","It was designed by our team."]]},
     examples:["We cut the maintenance time in half by pre-loading the diagnostics.","By checking the log first, you avoid repeating the whole test.","You can improve your listening by watching short clips without subtitles.","The panel comes off by pressing the two clips, not with a screwdriver."],
     watch:"After “by”, always use -ing: “by checking”, never “by check” or “by to check”."} ],
  speaking:[
    {kind:"Negotiation", text:"Plan a trip with your partner. Every proposal must be stated with “would rather” or “would prefer”, and one of you must use “I’d rather you…” at least twice."},
    {kind:"How-to", text:"Explain how you achieved something — saved money, learned a skill, fixed a problem — in five steps, every step using “by + gerund”."},
    {kind:"Polite pushback", text:"Your partner suggests five things you dislike. Decline each one with a different preference structure and a reason."} ],
  tips:[
    "“Rather” + bare verb + than; “prefer” + to + verb + to.",
    "“I’d rather you didn’t” uses a past form for a present request.",
    "After “by”, always -ing."],
  quiz:{q:"We reduced the error rate ___ every entry twice.", options:["by checking","by check","for checking"], answer:0, explain:"“By” is a preposition of method and is always followed by a gerund: “by checking”."} }
];
